import numpy as np, json, pickle, sys, time
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from rcb_client import Robot
from PIL import Image
S=json.load(open('/app/output/spec.json'))
P=np.array(S['arm']['position_m']); AX=np.array(S['arm']['axis']); EE=np.array(S['arm']['end_effector']['position_m'])
def tf(q):
 T=np.eye(4)
 for p,a,v in zip(P,AX,q):
  R=Rotation.from_rotvec(a*v).as_matrix(); A=np.eye(4); A[:3,:3]=R; A[:3,3]=p-R@p; T=T@A
 return T
def base(b):
 T=np.eye(4); T[:3,:3]=Rotation.from_euler('z',b[2]).as_matrix(); T[:2,3]=b[:2]; return T
def fk(o):
 T=base(o['proprio']['base_pose'])@tf(o['proprio']['arm_pos']); return T[:3,:3]@EE+T[:3,3],T[:3,:3]
def camera(o):
 T=base(o['proprio']['base_pose'])@tf(o['proprio']['arm_pos']); c=S['cameras']['robot_wrist']['pose']; return T[:3,:3]@c['position_m']+T[:3,3],T[:3,:3]@np.array([c['right'],c['up'],c['forward']]).T
def point(o,u,v):
 c,R=camera(o); d=o['depth']['robot_wrist'][int(v),int(u)]; f=240/np.tan(np.deg2rad(41.8)/2); return c+R@np.array([(u-319.5)/f*d,-(v-239.5)/f*d,d])
def save(o):
 pickle.dump(o,open('/app/output/obs.pkl','wb'))
 for k,v in o.get('images',{}).items(): Image.fromarray(v).save('/app/output/'+k+'.png')
 print('OBS',o['step'],o['done'],o['reason'],'grip',o['proprio']['gripper_pos'],'base',o['proprio']['base_pose'],'ee',fk(o)[0].round(4).tolist(),flush=True)
class Control:
 def __init__(self):
  self.r=Robot(); self.o=self.r.observe(); self.g=0; self.actions=[]; save(self.o)
 def step(self,a,images=False):
  a=np.array(a).tolist(); self.actions.extend(a if np.array(a).ndim==2 else [a]); json.dump(self.actions,open('/app/output/actions.json','w')); self.o=self.r.step('delta',a,images=images); return self.o
 def obs(self): self.o=self.r.observe();save(self.o)
 def wait(self,n=5,g=None):
  if g is not None:self.g=g
  self.step([[0]*10+[self.g]]*n); self.obs()
 def move(self,p,R=None,n=80):
  q=np.array(self.o['proprio']['arm_pos']); B=base(self.o['proprio']['base_pose']); p=np.array(p); R=fk(self.o)[1] if R is None else np.array(R)
  def fun(x):
   T=B@tf(x); pos=T[:3,:3]@EE+T[:3,3]; rot=Rotation.from_matrix(R.T@T[:3,:3]).as_rotvec();return np.r_[10*(pos-p),rot,.015*(x-q)]
  low=np.array([-30,-2.24,-30,-2.57,-30,-2.09,-30]);high=-low
  sol=least_squares(fun,q,bounds=(low,high),max_nfev=200)
  print('IK',sol.x.round(3).tolist(),'err',fun(sol.x)[:6].round(4).tolist(),flush=True)
  self.joints(sol.x,n)
 def joints(self,q,n=80):
  for i in range(n):
   e=np.array(q)-self.o['proprio']['arm_pos']
   if max(abs(e))<.006:break
   self.step([0,0,0]+np.clip(e,-.1,.1).tolist()+[self.g])
   if self.o['done']:break
  self.obs()
 def drive(self,d,n=10):
  self.step([list(np.array(d)/n)+[0]*7+[self.g]]*n); self.obs()
 def reset(self):
  self.o=self.r.reset();self.g=0;self.actions=[];json.dump([],open('/app/output/actions.json','w'));save(self.o)
 def points(self,uvs):
  for u,v in uvs:print((u,v),point(self.o,u,v).round(4).tolist(),flush=True)
C=Control()
for line in sys.stdin:
 try: exec(line)
 except Exception as e: print(type(e).__name__,str(e),flush=True)
